export const LEARNING_TRACKS = [{"id": "osint", "name": "OSINT", "description": "Observer, vérifier et documenter des informations publiques.", "tools": ["Bellingcat Toolkit", "SpiderFoot", "Amass"], "sources": ["https://bellingcat.gitbook.io/toolkit", "https://owasp.org/www-project-amass/"], "lessons": [{"id": "osint-1", "title": "Cadrer une recherche et qualifier les sources", "level": 1, "duration": 45, "goal": "Définir une question vérifiable et distinguer fait, hypothèse et reprise.", "prerequisite": "Aucun prérequis technique.", "concept": "Une investigation commence par une question précise, une période et un périmètre. Une information publique peut être fausse, ancienne ou sortie de son contexte. Une publication qui cite un autre article n’est pas une confirmation indépendante. Conserve le lien, la date de consultation, la date du fait et le passage qui soutient chaque affirmation. Évalue la proximité de la source avec le fait : document original, témoin, analyse ou simple reprise. Une absence de résultat n’est pas une preuve d’absence.", "steps": ["Choisis une annonce publique d’une organisation.", "Retrouve le communiqué original et deux articles qui le citent.", "Crée un tableau : affirmation, URL, date, preuve, incertitude.", "Écris trois faits établis et une question non résolue."], "expected": "Un dossier sourcé qui distingue les reprises des preuves indépendantes.", "pitfall": "Confondre trois reprises d’une même dépêche avec trois confirmations.", "question": "Trois articles citent le même communiqué : combien de sources primaires ?", "answer": "Une seule ; les trois articles sont des reprises de cette source.", "lab": {"setup": "Ouvre un navigateur et un tableur. Choisis une annonce de version sur le dépôt officiel github.com/volatilityfoundation/volatility3/releases.", "why": "Une source primaire publie le fait directement ; une reprise le raconte. Le nombre de pages ne représente pas le nombre de confirmations indépendantes.", "action": "Crée les colonnes : affirmation | URL | passage exact | date publiée | consulté le | limite.\nLigne 1 : une version a été publiée | URL de la release | titre et tag | date affichée | aujourd’hui | auteur du projet, pas validation indépendante.", "output": "Une ligne traçable, avec un tag exact et un lien vers la page de la version, sans supposer qu’il s’agit de la version installée chez toi.", "interpret": "Ouvre les notes et distingue fonctionnalités annoncées et corrections effectivement documentées. Cherche ensuite une reprise qui cite cette release ; marque-la dépendante de la même source.", "trouble": "Ne confonds pas dernière release, dernier commit et dernière version stable. Si une date manque, écris non fournie. Le résultat du moteur n’est pas une preuve suffisante : lis la page.", "exercise": "Une reprise affirme « compatible avec tous les systèmes », mais la release ne le dit pas. Comment remplir le tableau ?", "solution": "Conserver cette affirmation comme non étayée et demander une documentation de compatibilité. Ne pas l’ajouter aux faits établis."}}, {"id": "osint-2", "title": "Vérifier une image et une chronologie", "level": 2, "duration": 60, "goal": "Comparer les indices visuels avec le contexte annoncé.", "prerequisite": "Avoir terminé le cadrage des sources.", "concept": "Une image ne prouve pas à elle seule une date ou un lieu. Les métadonnées peuvent être absentes, modifiées ou provenir d’une copie. Compare bâtiments, relief, signalétique, météo et chronologie avec des références publiques. La recherche inversée peut révéler une publication antérieure, sans garantir qu’il s’agit de la première apparition. Garde des hypothèses concurrentes et explique pourquoi tu en retiens une.", "steps": ["Prends une photo de ton propre environnement, sans personnes identifiables.", "Compare une copie redimensionnée et le fichier original.", "Relève trois indices vérifiables et deux limites.", "Construis une chronologie des versions et rédige une conclusion prudente."], "expected": "Une conclusion assortie d’un degré de confiance et de ses limites.", "pitfall": "Traiter une date de fichier comme la date certaine de prise de vue.", "question": "Une recherche inversée trouve une image plus ancienne : que démontre-t-elle ?", "answer": "Que cette version existait déjà à cette date ; pas nécessairement son origine exacte.", "lab": {"setup": "Prends une photo d’un objet chez toi sans personne ni adresse, conserve son original et crée une copie redimensionnée. Installe ExifTool depuis exiftool.org si tu souhaites utiliser le terminal.", "why": "EXIF décrit des métadonnées enregistrées dans le fichier. Une plateforme peut les supprimer ; elles peuvent aussi être modifiées. Un indice visuel et une métadonnée sont deux observations différentes.", "action": "exiftool -G1 -a -s original.jpg\nexiftool -G1 -a -s copie.jpg\n# Compare DateTimeOriginal, dimensions et présence éventuelle de GPS.", "output": "Les dimensions peuvent changer et certaines métadonnées disparaître. Aucun champ n’est garanti selon l’appareil et le logiciel utilisés.", "interpret": "Relève trois détails visibles et indique lesquels survivent au redimensionnement. Une date EXIF décrit une déclaration du fichier ; la date de copie du système ne date pas forcément la prise de vue.", "trouble": "Si ExifTool manque, utilise les propriétés de l’image pour une première observation. N’envoie pas une photo privée dans un moteur de recherche inversée. Une absence de GPS ne prouve pas l’absence d’un lieu identifiable.", "exercise": "La copie porte une date de modification plus récente mais montre le même objet. Peut-on dater la scène avec cette seule date ?", "solution": "Non : elle peut dater la création de la copie. Il faut distinguer date du fichier et date du fait représenté."}}, {"id": "osint-3", "title": "Construire un dossier reproductible", "level": 3, "duration": 75, "goal": "Organiser les preuves, les liens entre entités et les contradictions.", "prerequisite": "Savoir qualifier une source et vérifier une chronologie.", "concept": "La reproductibilité permet à une autre personne de suivre ton raisonnement. Attribue un identifiant à chaque élément, conserve son origine et note les transformations effectuées. Un graphe de liens représente des relations documentées, pas une culpabilité ou une attribution automatique. Réduis la collecte aux données nécessaires à la question et sépare clairement les faits des interprétations.", "steps": ["Utilise les annonces publiques d’un projet open source.", "Relie annonces, dépôts et documents de version.", "Fais relire une hypothèse par un tiers à partir de tes sources.", "Rédige une synthèse avec contradictions, confiance et pistes restantes."], "expected": "Un dossier que l’on peut reproduire sans deviner tes étapes.", "pitfall": "Présenter une relation de graphe comme une preuve d’attribution.", "question": "Pourquoi conserver les contradictions ?", "answer": "Elles permettent de tester les hypothèses et évitent de sélectionner uniquement les preuves favorables.", "lab": {"setup": "Réutilise la release étudiée au niveau 1. Crée un dossier avec un fichier sources.csv, notes.md et conclusion.md.", "why": "Une piste devient vérifiable quand une autre personne peut retrouver chaque élément et reconstruire le raisonnement. Un lien entre deux pages ne prouve pas une attribution humaine.", "action": "Dans sources.csv : S1, URL de release, date, tag\nDans notes.md : H1 = ce tag correspond à la version annoncée ; soutien = S1 ; limite = installation locale non vérifiée\nDans conclusion.md : faits, hypothèses, contradictions, éléments manquants.", "output": "Chaque phrase factuelle de la conclusion renvoie à un identifiant de source. Les inconnues restent explicitement séparées des faits.", "interpret": "Retrouve le tag dans le dépôt puis compare avec la release. Un tag est une référence Git ; une release est une publication attachée à un tag. Cette différence explique pourquoi ils peuvent porter des dates distinctes.", "trouble": "N’enregistre pas de secrets ni de profils personnels sans nécessité. Si un lien change, conserve au minimum le titre, le tag, la date de consultation et le passage utilisé.", "exercise": "Un lecteur ne retrouve pas une affirmation dans S1. Que faut-il modifier ?", "solution": "Ajouter la source exacte et le passage qui la soutient ou rétrograder l’affirmation en hypothèse non confirmée."}}]}, {"id": "forensic", "name": "Forensic", "description": "Préserver et interpréter des traces numériques.", "tools": ["Volatility 3", "Autopsy", "The Sleuth Kit"], "sources": ["https://volatility3.readthedocs.io/en/stable/", "https://www.sleuthkit.org/autopsy/"], "lessons": [{"id": "forensic-1", "title": "Préserver les données et calculer une empreinte", "level": 1, "duration": 45, "goal": "Comprendre l’intégrité et travailler sur une copie.", "prerequisite": "Savoir manipuler des fichiers et ouvrir un terminal.", "concept": "L’analyse modifie parfois les données étudiées : ouverture, indexation et montage peuvent changer des métadonnées. Une copie de travail et une journalisation des opérations limitent ce risque. Une empreinte SHA-256 sert à comparer des contenus ; elle ne prouve ni leur auteur ni leur date de création. La chaîne de conservation décrit qui a acquis, transféré et analysé les données, et avec quelles méthodes.", "steps": ["Crée un fichier texte fictif et sa copie.", "Calcule leur SHA-256 avec sha256sum ou Get-FileHash.", "Modifie uniquement la copie, puis recalcule son empreinte.", "Note les opérations et leurs horaires dans un journal."], "expected": "Deux empreintes identiques avant modification, puis différentes après.", "pitfall": "Analyser directement un support original sans documenter les modifications.", "question": "Une empreinte identique prouve-t-elle l’identité de l’auteur ?", "answer": "Non. Elle soutient l’identité du contenu comparé, pas sa provenance humaine.", "lab": {"setup": "Crée un dossier de travail sur ton ordinateur. Les fichiers de cet exercice sont fictifs ; aucune image disque n’est nécessaire.", "why": "SHA-256 calcule une empreinte de 256 bits, affichée avec 64 caractères hexadécimaux. Changer un octet modifie normalement toute l’empreinte ; une copie identique conserve la même.", "action": "Linux/macOS :\nprintf \"preuve fictive\\n\" > original.txt\ncp original.txt copie.txt\n# Linux : sha256sum original.txt copie.txt\n# macOS : shasum -a 256 original.txt copie.txt\n\nPowerShell :\nSet-Content original.txt \"preuve fictive\"\nCopy-Item original.txt copie.txt\nGet-FileHash original.txt,copie.txt -Algorithm SHA256", "output": "Les deux lignes montrent la même empreinte de 64 caractères avant modification.", "interpret": "Ajoute un caractère uniquement à copie.txt puis recalcule. Seule son empreinte doit changer. N’attends pas la même valeur entre Windows et Linux : encodage et fin de ligne peuvent différer.", "trouble": "Une différence avant modification indique déjà un contenu différent. Vérifie que tu compares les bons chemins et non le nom du fichier. Garde original.txt intact et note chaque opération.", "exercise": "Explique pourquoi deux fichiers de même nom peuvent avoir des empreintes différentes.", "solution": "Le nom n’entre pas dans l’empreinte du contenu. Des octets différents, même invisibles comme une fin de ligne, produisent une empreinte différente."}}, {"id": "forensic-2", "title": "Assembler une chronologie système", "level": 2, "duration": 60, "goal": "Interpréter plusieurs familles de traces et leurs fuseaux horaires.", "prerequisite": "Avoir assimilé les principes de préservation.", "concept": "Les journaux, métadonnées de fichiers et événements applicatifs racontent des parties différentes d’une activité. Certains événements sont différés ou perdus. Normalise les horaires, conserve le fuseau original et vérifie l’horloge de l’hôte. Une ouverture de fichier ou une connexion réseau ne démontre pas à elle seule une action malveillante. La corrélation doit rester compatible avec les autres traces.", "steps": ["Crée des journaux fictifs avec deux fuseaux horaires.", "Normalise les heures en UTC dans un tableau.", "Rapproche création de fichier, connexion et événement applicatif.", "Ajoute une explication alternative pour chaque conclusion."], "expected": "Une chronologie explicable qui distingue observation et interprétation.", "pitfall": "Mélanger heures locales et UTC ou ignorer un décalage d’horloge.", "question": "Deux événements proches dans le temps prouvent-ils un lien causal ?", "answer": "Non ; il faut des éléments qui relient leurs processus, utilisateurs ou objets.", "lab": {"setup": "Dans un tableur ou un éditeur, recopie les trois traces fictives ci-dessous. Ajoute les colonnes heure UTC, source et interprétation.", "why": "Un décalage +02:00 signifie que l’heure locale est deux heures en avance sur UTC. La normalisation rend les traces comparables sans démontrer de causalité.", "action": "2026-10-15T10:00:00+02:00 | application | ouverture session user-test\n2026-10-15T08:00:05Z      | système     | création rapport.txt\n2026-10-15T09:59:59+02:00 | réseau      | connexion depuis poste-test", "output": "07:59:59 UTC : connexion\n08:00:00 UTC : session\n08:00:05 UTC : création", "interpret": "Soustrais deux heures aux traces +02:00 et conserve Z tel quel : Z signifie UTC. Trie ensuite. Pour relier les événements, il manquerait un identifiant de session, un processus et une horloge fiable.", "trouble": "Ne supprime pas les valeurs originales. Si une trace n’indique pas de fuseau, marque-le inconnu au lieu d’en inventer un. Un décalage d’horloge peut inverser l’ordre apparent.", "exercise": "Une quatrième trace indique 08:00:03Z avec une horloge connue pour avancer de 10 secondes. Où se place-t-elle ?", "solution": "L’heure corrigée est 07:59:53 UTC, avant les trois autres événements. Il faut conserver la valeur observée et la justification de la correction."}}, {"id": "forensic-3", "title": "Introduire l’analyse mémoire avec Volatility 3", "level": 3, "duration": 75, "goal": "Relier processus, réseau et modules sur une image de laboratoire.", "prerequisite": "Connaître processus, mémoire virtuelle et principes de conservation.", "concept": "Une image mémoire décrit un état partiel à un instant donné. Les résultats dépendent du système, de la qualité de l’acquisition et des symboles utilisés. Volatility 3 propose des plugins pour explorer processus, connexions et structures système. Un processus masqué ou un module atypique est une piste, pas un verdict : vérifie plusieurs vues et la cohérence des structures.", "steps": ["Choisis une image mémoire de formation autorisée.", "Consulte les prérequis et plugins de la documentation de ta version.", "Compare deux vues des processus et leurs relations parent-enfant.", "Relie les observations aux traces réseau et note les limites de l’image."], "expected": "Un rapport reliant des observations mémoire à des hypothèses justifiées.", "pitfall": "Prendre tout résultat d’un plugin pour une preuve définitive.", "question": "Pourquoi relever la version de l’outil et les symboles ?", "answer": "Pour expliquer la compatibilité, les limites et reproduire l’analyse.", "lab": {"setup": "Installe Git et Python 3. Utilise une image mémoire de formation explicitement autorisée et note sa provenance et son SHA-256. Les plugins windows.* nécessitent une image Windows ; ne les applique pas à une image Linux.", "why": "Un processus possède un identifiant PID et souvent un parent PPID. pslist parcourt la liste des processus ; psscan recherche des structures en mémoire et peut retrouver des processus terminés. Les deux vues peuvent donc différer sans malware.", "action": "git clone https://github.com/volatilityfoundation/volatility3.git\ncd volatility3\npython3 -m venv .venv\n# Linux/macOS : . .venv/bin/activate\n# Windows : .venv\\Scripts\\Activate.ps1\npython -m pip install -e .\npython vol.py -h\npython vol.py -f /chemin/image.raw windows.info\npython vol.py -f /chemin/image.raw windows.pslist\npython vol.py -f /chemin/image.raw windows.psscan", "output": "Une image compatible fournit des informations système puis des lignes de processus : PID, PPID, nom et parfois dates. Les valeurs dépendent entièrement de l’image.", "interpret": "Remplace /chemin/image.raw par ton fichier. Commence par windows.info pour contrôler la compatibilité. Compare un même PID dans les deux vues, puis recherche windows.pstree dans l’aide pour visualiser les parents. Note les résultats absents au lieu de les assimiler à une dissimulation.", "trouble": "Une erreur de symboles n’est pas une preuve d’altération : vérifie la documentation et l’accès aux symboles. Ne contourne pas les politiques PowerShell ; utilise le Python du dossier .venv directement si nécessaire.", "exercise": "Un PID est présent dans psscan mais absent de pslist. Donne deux hypothèses et un contrôle supplémentaire.", "solution": "Processus terminé dont les traces subsistent, ou incohérence/masquage à investiguer. Vérifier les dates de sortie, l’arbre des processus et les autres traces avant de conclure."}}]}, {"id": "pentest", "name": "Pentest", "description": "Apprendre une démarche de test dans un laboratoire autorisé.", "tools": ["Burp Suite Community", "Nmap", "OWASP ZAP"], "sources": ["https://portswigger.net/web-security/learning-paths", "https://www.zaproxy.org/getting-started/"], "lessons": [{"id": "pentest-1", "title": "Préparer le périmètre et cartographier un laboratoire", "level": 1, "duration": 45, "goal": "Distinguer surface exposée, vulnérabilité et risque.", "prerequisite": "Bases TCP/IP et machine de laboratoire dont tu maîtrises l’accès.", "concept": "Un test utile commence par un périmètre écrit : hôtes, comptes, horaires, actions autorisées et arrêt en cas d’impact. Un port ouvert indique un service accessible, pas une vulnérabilité. L’inventaire relie interfaces, applications et dépendances. Documente chaque observation avant de proposer une hypothèse de faiblesse et vérifie que le service identifié correspond réellement à la version annoncée.", "steps": ["Déploie une application locale de formation.", "Liste ses ports documentés et ses comptes de test.", "Compare les services attendus aux connexions observées sur ton hôte.", "Établis une liste de tests sans lancer d’actions hors du laboratoire."], "expected": "Un périmètre et une cartographie vérifiables.", "pitfall": "Scanner une cible tiers parce qu’elle est accessible sur Internet.", "question": "Un service ouvert implique-t-il une faille exploitable ?", "answer": "Non. Le risque dépend de la configuration, des contrôles et du contexte.", "lab": {"setup": "Sur un ordinateur avec Python 3, ouvre un terminal dans un dossier neuf. Le serveur sera accessible seulement sur la boucle locale. Sur Windows, remplace python3 par py si nécessaire.", "why": "Un serveur écoute une adresse et un port. 127.0.0.1 désigne ton ordinateur ; 8000 identifie le service. Un port accessible ne démontre aucune faille.", "action": "mkdir labo-web\ncd labo-web\npython3 -m http.server 8000 --bind 127.0.0.1", "output": "Serving HTTP on 127.0.0.1 port 8000 ...", "interpret": "Garde ce terminal ouvert, puis visite http://127.0.0.1:8000 dans le navigateur. Une liste de dossier apparaît. Le navigateur est le client ; Python répond aux requêtes. Une ligne GET apparaît dans le terminal pour chaque ressource demandée. Arrête avec Ctrl+C.", "trouble": "Si le port est occupé, utilise 8001 et change aussi l’URL. Si python3 est introuvable, installe Python depuis python.org. Ne lance pas ce serveur dans un dossier contenant tes documents personnels.", "exercise": "Ouvre /absent.txt sur le même serveur. Compare avec la page d’accueil : quelle différence observes-tu ?", "solution": "La page inexistante renvoie 404 ; la page présente renvoie 200. Le code décrit la réponse, pas la sécurité globale du service."}}, {"id": "pentest-2", "title": "Comprendre HTTP, sessions et contrôles d’accès", "level": 2, "duration": 60, "goal": "Observer le chemin d’une requête avec un proxy de laboratoire.", "prerequisite": "Avoir préparé un laboratoire et connaître URL, méthode et en-têtes.", "concept": "Une session associe des requêtes à une identité, mais l’authentification ne suffit pas à autoriser chaque action. Les contrôles doivent vérifier le droit d’agir sur un objet à chaque requête. Un proxy comme Burp ou ZAP permet d’examiner les échanges d’une application de formation. Modifie une variable à la fois et compare le résultat avec une référence pour éviter les conclusions hâtives.", "steps": ["Ouvre un laboratoire débutant de la Web Security Academy.", "Observe une requête et identifie ses paramètres et cookies.", "Compare deux comptes de test dans le scénario pédagogique.", "Rédige la différence entre identité et permission sur un objet."], "expected": "Un schéma HTTP et une observation reproductible du contrôle d’accès.", "pitfall": "Assimiler un changement de code HTTP à une preuve d’exploitation.", "question": "Pourquoi vérifier les droits côté serveur à chaque requête ?", "answer": "Un client peut modifier ses paramètres ; il ne constitue pas une frontière de confiance.", "lab": {"setup": "Relance le serveur local de la leçon 1. Crée un fichier bonjour.txt contenant Bonjour dans labo-web. Ouvre les outils de développement du navigateur, onglet Réseau.", "why": "HTTP contient une méthode, un chemin et des en-têtes. Le corps transporte le contenu. Une session réelle peut utiliser un cookie, mais ce serveur de fichiers n’implémente ni connexion ni autorisation.", "action": "Dans le navigateur : http://127.0.0.1:8000/bonjour.txt\nDans un second terminal :\ncurl -i http://127.0.0.1:8000/bonjour.txt", "output": "HTTP/1.0 200 OK\nContent-type: text/plain\n...\nBonjour", "interpret": "L’option -i montre les en-têtes puis une ligne vide et le corps. Dans Réseau, sélectionne bonjour.txt : la méthode est GET et le chemin /bonjour.txt. HTTP/1.0 ici décrit ce serveur pédagogique ; les applications modernes peuvent utiliser HTTP/2 ou HTTP/3.", "trouble": "Sur Windows PowerShell, utilise curl.exe pour éviter l’ancien alias Invoke-WebRequest. Si curl manque, l’onglet Réseau suffit. Aucun certificat de proxy n’est nécessaire pour ce laboratoire HTTP local.", "exercise": "Demande /bonjour.txt puis /inexistant.txt et relève méthode, chemin, statut et taille. Pourquoi ce test ne vérifie-t-il pas les droits entre utilisateurs ?", "solution": "200 puis 404 distinguent présence et absence. Aucun compte ni objet protégé n’existe dans ce laboratoire : il ne permet pas de conclure sur les contrôles d’accès. Pour cela, utilise ensuite un laboratoire Access Control de PortSwigger."}}, {"id": "pentest-3", "title": "Produire une preuve et vérifier la correction", "level": 3, "duration": 75, "goal": "Transformer un constat de laboratoire en rapport exploitable.", "prerequisite": "Savoir observer des requêtes et comparer des comptes de test.", "concept": "Un rapport distingue prérequis, étapes reproductibles, résultat observé et impact plausible. Une preuve minimale démontre le problème sans multiplier les actions ni collecter inutilement des données. La correction doit traiter la cause plutôt qu’un seul exemple. Un nouveau test vérifie le scénario initial et les cas voisins pour réduire le risque de contournement.", "steps": ["Reprends un laboratoire déjà résolu.", "Écris les prérequis et une preuve minimale sur les données fictives.", "Propose un contrôle serveur et un test de non-régression.", "Évalue les limites de la démonstration et le risque résiduel."], "expected": "Un rapport court, reproductible et orienté correction.", "pitfall": "Exagérer un impact qui n’a pas été démontré dans le périmètre.", "question": "Pourquoi un test de non-régression est-il nécessaire ?", "answer": "Pour vérifier que la cause est corrigée et que le comportement attendu demeure stable.", "lab": {"setup": "Conserve le serveur de la leçon 1 et crée un fichier fictif brouillon.txt qui ne doit plus être publié. N’utilise aucune donnée réelle.", "why": "Une preuve utile relie un comportement observé à un résultat attendu. La correction doit être vérifiée avec un cas négatif et un cas positif : bloquer l’indésirable tout en gardant le service utile.", "action": "curl -i http://127.0.0.1:8000/brouillon.txt\n# Déplace ensuite brouillon.txt hors de labo-web avec le gestionnaire de fichiers.\ncurl -i http://127.0.0.1:8000/brouillon.txt\ncurl -i http://127.0.0.1:8000/bonjour.txt", "output": "Avant : brouillon.txt → 200\nAprès : brouillon.txt → 404\nAprès : bonjour.txt → 200", "interpret": "Le constat est une publication involontaire de fichier fictif. La correction enlève le fichier de la racine publiée. Un vrai espace privé demanderait une authentification et une autorisation serveur ; renommer le fichier ne constitue pas cette protection.", "trouble": "Si le fichier est encore visible, vérifie le dossier du serveur et désactive le cache dans Réseau. Conserve heure, chemin et statut, sans recopier de données sensibles.", "exercise": "Rédige un rapport de cinq lignes : périmètre, preuve, impact démontré, correction, résultat du nouveau test.", "solution": "Exemple : serveur local uniquement ; GET /brouillon.txt donne 200 ; lecture d’un fichier fictif non destiné au public ; déplacement hors racine ; 404 sur brouillon et 200 sur bonjour. Aucun impact au-delà du laboratoire n’est affirmé."}}]}, {"id": "defense", "name": "Défense", "description": "Détecter, prioriser et répondre à une activité suspecte.", "tools": ["Sigma", "Suricata", "Wazuh"], "sources": ["https://sigmahq.io/docs/", "https://documentation.wazuh.com/current/"], "lessons": [{"id": "defense-1", "title": "Choisir les journaux utiles", "level": 1, "duration": 45, "goal": "Relier une question de détection à une source de télémétrie.", "prerequisite": "Connaître processus, authentification et connexions réseau.", "concept": "Une détection dépend d’abord de ce qui est observable. Choisis les journaux à partir d’un comportement à vérifier, puis contrôle leur couverture, leur horodatage et leur acheminement. Collecter davantage sans objectif augmente le bruit et les coûts. Définis la durée de conservation et les accès aux données, puis vérifie les pertes et les champs manquants.", "steps": ["Choisis un événement normal d’authentification dans un laboratoire.", "Identifie le journal et les champs qui l’expliquent.", "Simule une interruption de collecte sur des données fictives.", "Décris ce que l’on peut et ne peut pas conclure."], "expected": "Une fiche de télémétrie avec couverture et limites.", "pitfall": "Créer une règle avant de vérifier que les événements existent.", "question": "Une absence d’alerte prouve-t-elle l’absence d’activité ?", "answer": "Non, elle peut provenir d’un manque de visibilité ou d’une règle inadaptée.", "lab": {"setup": "Utilise un éditeur de texte pour créer les événements fictifs ci-dessous. Aucun agent de collecte ni SIEM n’est requis pour comprendre ce premier exercice.", "why": "Un journal est une suite d’observations structurées. Une détection ne peut fonctionner que si ses champs sont collectés et si les événements arrivent. Absence d’alerte et absence d’événement sont deux choses différentes.", "action": "{\"time\":\"2026-10-15T08:00:00Z\",\"host\":\"labo\",\"user\":\"alice-test\",\"action\":\"login\",\"result\":\"failure\"}\n{\"time\":\"2026-10-15T08:00:05Z\",\"host\":\"labo\",\"user\":\"alice-test\",\"action\":\"login\",\"result\":\"success\"}", "output": "Deux événements, même hôte et utilisateur, résultats différents et heures séparées de cinq secondes.", "interpret": "Liste les champs indispensables pour répondre à « y a-t-il un succès après un échec ? » : heure, utilisateur, hôte et résultat. Pour distinguer deux connexions depuis des machines différentes, il faudrait aussi une adresse source.", "trouble": "Un champ absent doit être marqué manquant. Ne déduis pas une adresse IP d’un nom d’utilisateur. Ces exemples ne correspondent pas au schéma Windows réel.", "exercise": "Supprime la première ligne : peut-on conclure que la connexion a réussi sans aucun échec ?", "solution": "On peut seulement constater un succès dans les données disponibles. Un échec peut avoir été perdu ou survenir hors période."}}, {"id": "defense-2", "title": "Lire et tester une règle Sigma", "level": 2, "duration": 60, "goal": "Comprendre sélection, condition et faux positifs.", "prerequisite": "Avoir identifié un journal et ses champs.", "concept": "Sigma décrit une logique de détection indépendante d’un backend particulier. Sa traduction dépend des champs disponibles et du moteur cible. Une règle doit être testée avec des événements positifs et négatifs, puis ajustée au contexte local. La gravité d’une alerte n’est pas la confiance : documente séparément impact, couverture et risque de faux positif.", "steps": ["Choisis une règle de formation dans la documentation Sigma.", "Relie chaque champ à un événement fictif.", "Construis deux exemples positifs et deux exemples négatifs.", "Explique une exception acceptable et son risque de masquer une attaque."], "expected": "Une matrice de tests avec faux positifs et limites.", "pitfall": "Copier une règle en production sans adapter le schéma des champs.", "question": "Pourquoi tester des événements négatifs ?", "answer": "Pour vérifier que la règle ne signale pas des activités normales proches du scénario.", "lab": {"setup": "Reprends les événements fictifs du niveau 1. Le YAML suivant est une règle pédagogique à lire ; ce n’est pas une commande et elle n’est pas directement déployable sans mapping du backend.", "why": "Une sélection compare des champs, puis condition combine les sélections. logsource indique la famille d’événements attendue. Sigma doit être converti et testé pour ton moteur et ton schéma.", "action": "title: Echec de connexion du laboratoire\nstatus: experimental\nlogsource:\n  category: authentication\ndetection:\n  selection:\n    action: login\n    result: failure\n  condition: selection\nlevel: low", "output": "Premier événement : correspondance. Deuxième événement : aucune correspondance. Un événement action=logout et result=failure ne correspond pas.", "interpret": "Les deux champs de selection sont combinés par ET. La règle détecte un échec isolé, pas une attaque par force brute. Une détection de répétition exige un regroupement et une fenêtre temporelle adaptés au moteur.", "trouble": "Si ton journal utilise outcome au lieu de result, adapte le mapping ; ne suppose pas que la conversion inventera le champ. Une règle qui ne déclenche jamais peut simplement manquer de données.", "exercise": "Construis quatre cas : login/failure, login/success, logout/failure, login avec result absent. Lesquels correspondent ?", "solution": "Seul login/failure correspond. Le champ absent n’est pas équivalent à failure. Vérifie ensuite avec un événement réel de laboratoire avant tout déploiement."}}, {"id": "defense-3", "title": "Trier un incident et conduire la réponse", "level": 3, "duration": 75, "goal": "Organiser collecte de preuves, confinement et retour d’expérience.", "prerequisite": "Savoir lire une alerte et interpréter ses limites.", "concept": "Une réponse proportionnée relie l’alerte au contexte de l’hôte et à l’activité métier. Préserve les preuves utiles avant une action irréversible lorsque la situation le permet. Le confinement réduit l’exposition ; l’éradication traite la cause ; la restauration remet le service en état. Définis des critères de sortie et des contrôles après remise en service.", "steps": ["Utilise un rapport public DFIR comme scénario sur table.", "Établis une chronologie, les actifs concernés et les inconnues.", "Propose trois actions avec bénéfices, risques et conditions d’arrêt.", "Rédige les critères de reprise et deux améliorations de détection."], "expected": "Un plan de réponse justifié plutôt qu’une suite d’actions automatiques.", "pitfall": "Supprimer des traces sans conservation ni mesure de l’impact.", "question": "Confinement et éradication sont-ils identiques ?", "answer": "Non : le confinement limite l’impact, l’éradication retire la cause et les mécanismes persistants.", "lab": {"setup": "Scénario fictif : plusieurs échecs puis un succès sur alice-test depuis un poste inconnu. Utilise un document partagé ou un cahier pour conduire la réponse sur table.", "why": "Le triage vérifie l’alerte. Le confinement limite les possibilités de propagation ; l’éradication enlève la cause ; la restauration remet en service. Une action peut détruire des preuves ou interrompre le métier.", "action": "08:00 : 5 échecs\n08:02 : 1 succès depuis poste-test-inconnu\n08:03 : changement d’un paramètre sensible\nTableau : observation | hypothèse | preuve à collecter | action | effet secondaire | critère de reprise", "output": "Un plan qui demande les journaux d’authentification et d’administration, vérifie avec le titulaire, puis décide d’une action proportionnée.", "interpret": "Un succès après des échecs est compatible avec un utilisateur qui corrige son mot de passe. Le changement sensible augmente la priorité mais ne prouve pas seul une compromission. Il faut vérifier session, source et validation du titulaire.", "trouble": "Ne supprime pas le compte ou les journaux dans cet exercice. Préserve la chronologie et la raison de chaque décision. Une désactivation réelle doit suivre les responsabilités du service.", "exercise": "Propose un critère de clôture plus solide que « plus d’alerte pendant une heure ».", "solution": "Cause expliquée et corrigée, sessions suspectes révoquées si nécessaire, contrôles validés, propriétaire informé et période de surveillance justifiée avec télémétrie fonctionnelle."}}]}, {"id": "network", "name": "Sécurité réseau", "description": "Observer les protocoles et concevoir des contrôles réseau.", "tools": ["Wireshark", "Zeek", "Suricata"], "sources": ["https://www.wireshark.org/docs/", "https://docs.zeek.org/en/current/", "https://docs.suricata.io/en/latest/"], "lessons": [{"id": "network-1", "title": "Lire TCP/IP, DNS et TLS", "level": 1, "duration": 45, "goal": "Comprendre ce qu’une capture révèle et ce qu’elle masque.", "prerequisite": "Bases d’utilisation d’un ordinateur et d’un réseau local.", "concept": "Une communication relie plusieurs couches : liaison, IP, transport et application. DNS résout des noms ; TCP organise un flux ; TLS chiffre son contenu et authentifie un pair selon sa configuration. Une capture peut révéler des métadonnées sans donner accès au contenu chiffré. Le point de capture détermine ce qui est visible : un paquet manquant peut simplement être hors du chemin observé.", "steps": ["Utilise une capture de formation sans données personnelles.", "Repère une résolution DNS et une connexion TCP.", "Observe les métadonnées d’un échange TLS sans tenter de le déchiffrer.", "Dessine le chemin probable et les limites du point de capture."], "expected": "Un schéma des couches et un relevé de métadonnées correctement interprétées.", "pitfall": "Conclure qu’aucun trafic n’existe à partir d’une capture prise au mauvais endroit.", "question": "TLS masque-t-il toutes les métadonnées ?", "answer": "Non. Certaines adresses, durées et tailles restent observables selon le contexte.", "lab": {"setup": "Relance le petit serveur Python du parcours Pentest. Installe Wireshark depuis wireshark.org. Choisis l’interface de boucle locale : lo, lo0 ou l’adaptateur loopback Npcap sous Windows.", "why": "TCP ouvre un flux avec SYN, SYN-ACK et ACK ; HTTP transporte ensuite la requête. Sur 127.0.0.1, aucune résolution DNS n’est nécessaire et cet exercice n’utilise pas TLS.", "action": "1. Lance la capture sur la boucle locale.\n2. Visite http://127.0.0.1:8000/bonjour.txt\n3. Arrête la capture.\n4. Filtre d’affichage Wireshark : tcp.port == 8000\n5. Pour HTTP seulement : http.request", "output": "Des paquets TCP puis une requête GET /bonjour.txt et une réponse, si le serveur est ouvert et si la bonne interface est capturée.", "interpret": "Clique sur un paquet, déplie Internet Protocol puis Transmission Control Protocol : adresse et port sont deux champs différents. Le port client est généralement temporaire ; le port serveur est 8000. Ce trafic HTTP est lisible car il n’est pas chiffré.", "trouble": "Un filtre d’affichage se saisit après capture ; ne le confonds pas avec un filtre de capture. Si rien n’apparaît, vérifie interface, serveur et filtre. Ne capture pas le trafic d’autres personnes.", "exercise": "Trouves-tu un paquet DNS ou TLS pour cette requête ? Pourquoi ?", "solution": "Non attendu : l’adresse IP est déjà connue et http:// ne demande pas TLS. Cela illustre pourquoi une absence doit être interprétée selon le scénario."}}, {"id": "network-2", "title": "Segmenter et vérifier les flux autorisés", "level": 2, "duration": 60, "goal": "Construire une matrice de communication et des tests.", "prerequisite": "Savoir distinguer adresses, ports et protocoles.", "concept": "La segmentation limite les chemins disponibles entre des zones de confiance. Une règle de filtrage doit correspondre à un besoin précis et être vérifiée dans les deux sens avec les flux de retour. Le comportement d’un pare-feu dépend de sa gestion d’état, de l’ordre des règles et des interfaces. Une architecture correcte sur le papier doit être confrontée aux chemins réels, notamment VPN et réseaux d’administration.", "steps": ["Crée trois zones fictives : utilisateurs, application et administration.", "Rédige les flux nécessaires et les refus attendus.", "Teste ces hypothèses sur un réseau de laboratoire isolé.", "Note la règle responsable et les traces de chaque test."], "expected": "Une matrice de flux avec preuves de fonctionnement et de refus.", "pitfall": "Croire qu’un VLAN seul garantit l’isolation.", "question": "Pourquoi contrôler l’ordre des règles ?", "answer": "Une règle précédente peut autoriser ou refuser un flux avant la règle que tu souhaites tester.", "lab": {"setup": "Sur papier, dessine trois zones : utilisateurs, application, administration. Le serveur local reste le seul service manipulé. Nous n’allons pas changer le pare-feu de ton ordinateur.", "why": "La segmentation définit les chemins autorisés. Une règle doit préciser source, destination, protocole, port et sens. Un VLAN distingue un réseau logique ; le filtrage contrôle les échanges entre réseaux.", "action": "Matrice proposée :\nUtilisateurs → Application | TCP 443 | autorisé\nAdministration → Application | TCP 22 | autorisé\nUtilisateurs → Administration | tous | refusé\nTout autre flux | refusé par défaut", "output": "Trois besoins explicites et une règle de fermeture. Pour chaque ligne, écris un test positif et un test négatif avant d’implémenter sur un réseau virtuel dédié.", "interpret": "Un pare-feu à états autorise généralement les réponses appartenant à une connexion établie. Il ne faut donc pas ajouter une règle inverse ouverte à tous les ports pour le retour. L’ordre des règles et le chemin réel doivent être vérifiés.", "trouble": "Un test vers un port fermé ne prouve pas le blocage du pare-feu : le service peut simplement ne pas écouter. Dans un laboratoire réel, vérifier d’abord le service depuis une source autorisée, puis examiner les journaux du filtrage.", "exercise": "Une règle autorise tout depuis Utilisateurs avant la règle de refus vers Administration. Quel problème cela pose-t-il ?", "solution": "Sur un moteur qui applique la première correspondance, l’autorisation gagne. Réordonner et tester depuis les deux zones ; documenter le comportement précis du moteur."}}, {"id": "network-3", "title": "Corréler Wireshark, Zeek et Suricata", "level": 3, "duration": 75, "goal": "Comparer paquet, événement réseau et alerte.", "prerequisite": "Avoir étudié les protocoles et la segmentation.", "concept": "Les outils répondent à des questions différentes : Wireshark détaille les paquets, Zeek produit des journaux structurés et Suricata peut signaler des motifs ou comportements. Une alerte nécessite une investigation ; l’absence d’alerte ne supprime pas la valeur des journaux. Corrèle les événements avec les adresses, les horaires et le contexte de capture, puis teste les hypothèses sur plusieurs vues.", "steps": ["Analyse le même PCAP de formation avec les outils disponibles.", "Compare une connexion dans Wireshark et conn.log de Zeek.", "Relie une alerte Suricata éventuelle aux paquets correspondants.", "Documente une explication bénigne et un élément qui permettrait de la départager."], "expected": "Une analyse croisée, avec visibilité et incertitudes explicites.", "pitfall": "Assimiler le nom d’une signature à une attribution certaine.", "question": "Pourquoi conserver le contexte du PCAP ?", "answer": "Il permet de comprendre la position de capture, les pertes et les limites de la corrélation.", "lab": {"setup": "Enregistre la capture locale du niveau 1 sous labo.pcap dans Wireshark. Installe Zeek et Suricata selon leurs documentations pour ta plateforme ; cette leçon lit un fichier hors ligne, sans ouvrir de port.", "why": "Wireshark expose les paquets, Zeek résume les connexions, Suricata applique ses décodeurs et règles. Un journal de connexion n’est pas une alerte. Une absence d’alerte sur un échange normal est attendue.", "action": "Dans un dossier vide :\nzeek -r /chemin/labo.pcap\n# Consulter conn.log et http.log produits.\n# Suricata : créer un autre dossier de sortie, puis :\nsuricata -r /chemin/labo.pcap -l /chemin/sortie-suricata", "output": "Zeek produit généralement conn.log et, pour cet HTTP, http.log. Suricata écrit ses journaux selon sa configuration ; aucune alerte n’est garantie.", "interpret": "Dans conn.log, rapproche id.orig_h, id.resp_h et id.resp_p du client, serveur et port 8000 observés dans Wireshark. uid relie les journaux Zeek entre eux, mais n’est pas un identifiant partagé automatiquement avec Suricata.", "trouble": "Remplace les chemins. Si les outils manquent ou si leur configuration échoue, reste sur Wireshark et lis la documentation d’installation. Une alerte nécessite un jeu de règles chargé ; ne fabrique pas un résultat attendu.", "exercise": "Si Suricata ne génère aucune alerte alors que Zeek voit la connexion, l’un des outils est-il nécessairement en panne ?", "solution": "Non : les objectifs diffèrent. Vérifie la lecture du PCAP, la configuration et les règles ; un trafic normal peut être journalisé sans déclencher de signature."}}]}, {"id": "dorks", "name": "Google dorks", "description": "Rechercher précisément des documents publics sans collecter de secrets.", "tools": ["Google Search", "Bing", "Recherche documentaire"], "sources": ["https://support.google.com/websearch/answer/2466433", "https://developers.google.com/search/docs/monitor-debug/search-operators/all-search-site"], "lessons": [{"id": "dorks-1", "title": "Combiner mots-clés, guillemets et site:", "level": 1, "duration": 45, "goal": "Réduire le bruit sur un domaine public choisi.", "prerequisite": "Avoir suivi le cadrage OSINT.", "concept": "Les opérateurs de recherche aident à exprimer une question, mais les moteurs n’indexent pas tout et n’interprètent pas toutes les combinaisons de la même façon. Les guillemets resserrent une expression ; site: limite un domaine ; le signe moins peut exclure un terme. Le nombre de résultats est une estimation. Une recherche sans résultat ne démontre pas qu’un document n’existe pas.", "steps": ["Choisis un domaine officiel ou ton propre site.", "Compare une recherche simple et une expression entre guillemets.", "Ajoute site: puis une exclusion pertinente.", "Note les différences et les limites de l’index."], "expected": "Une requête documentée avec justification de chaque opérateur.", "pitfall": "Présenter le nombre de résultats comme un inventaire exhaustif.", "question": "Que signifie zéro résultat ?", "answer": "Seulement qu’aucun résultat n’a été retourné pour cette requête à cet instant.", "lab": {"setup": "Ouvre un moteur de recherche dans ton navigateur. Cet exercice porte uniquement sur la documentation publique de l’ANSSI, pas sur des documents privés.", "why": "Un moteur interroge son index, pas Internet en direct. site: réduit le domaine ; les guillemets demandent une expression plus précise. Les résultats changent avec la langue, la date et le moteur.", "action": "Compare successivement :\nANSSI guide hygiène informatique\nsite:cyber.gouv.fr hygiène informatique\nsite:cyber.gouv.fr \"hygiène informatique\"\nsite:cyber.gouv.fr \"hygiène informatique\" -recrutement", "output": "La sélection se resserre généralement. Le nombre et l’ordre ne sont pas fixes ; conserve une capture de tes requêtes et les liens effectivement pertinents.", "interpret": "N’ajoute aucun espace entre site: et le domaine. Le terme exclu commence par un signe moins. Ouvre une page officielle et vérifie si le texte répond réellement à ta question.", "trouble": "Si une expression donne zéro résultat, retire un opérateur à la fois ; ne conclus pas que le guide n’existe pas. Certains moteurs interprètent différemment les accents et les opérateurs.", "exercise": "Quelle requête cherche l’expression exacte « authentification multifacteur » sur cyber.gouv.fr ?", "solution": "site:cyber.gouv.fr \"authentification multifacteur\". Puis lire les pages et noter les limites de la recherche."}}, {"id": "dorks-2", "title": "Retrouver des rapports et versions publiques", "level": 2, "duration": 60, "goal": "Cibler un format documentaire et confirmer la date.", "prerequisite": "Savoir utiliser guillemets et site:.", "concept": "filetype: peut orienter une recherche vers des rapports publics, tandis que intitle: cherche des mots dans le titre indexé. Ces opérateurs ne remplacent pas la lecture du document et de son contexte. Les dates affichées par le moteur peuvent correspondre à une mise à jour ou à une estimation. Vérifie la date dans le document et sur sa page d’origine, et conserve l’URL canonique.", "steps": ["Sur un domaine institutionnel, cherche un rapport public avec site: et filetype:pdf.", "Compare une requête intitle: avec une recherche dans le texte.", "Ouvre la page de publication et vérifie la date.", "Rédige une citation avec version et date de consultation."], "expected": "Une source primaire datée, plutôt qu’un lien isolé trouvé dans un moteur.", "pitfall": "Rechercher des identifiants, documents privés ou listes de personnes hors d’un périmètre autorisé.", "question": "La date du moteur suffit-elle à dater le rapport ?", "answer": "Non. Il faut vérifier le document, sa version et son contexte de publication.", "lab": {"setup": "Garde le domaine institutionnel du niveau 1 et prépare un tableau titre, URL du document, URL de publication, version et date.", "why": "filetype:pdf vise un format indexé ; intitle: vise le titre indexé. Aucun opérateur ne garantit la date ou l’authenticité : la vérification se fait sur la page et le document.", "action": "site:cyber.gouv.fr filetype:pdf \"hygiène informatique\"\nsite:cyber.gouv.fr intitle:guide \"hygiène\"", "output": "Des documents ou pages pertinents peuvent apparaître. Si aucun PDF n’est retourné, passe par la page officielle du guide ; ce n’est pas une preuve d’absence.", "interpret": "Ouvre le PDF depuis son domaine officiel, relève le titre et la version dans le document, puis retrouve sa page de publication. La date du moteur peut dater une réindexation, pas la publication.", "trouble": "Un intitulé trouvé dans un extrait peut être ancien. Compare la page actuelle et le document. Ne télécharge pas d’exécutables pour consulter un PDF.", "exercise": "Deux PDF portent le même titre avec deux dates. Comment choisir la citation ?", "solution": "Identifier version et page canonique, expliquer la version utilisée et sa pertinence. Ne pas choisir automatiquement la date la plus récente du moteur."}}, {"id": "dorks-3", "title": "Auditer l’exposition de ses propres documents", "level": 3, "duration": 75, "goal": "Distinguer indexation publique, autorisation et remédiation.", "prerequisite": "Savoir identifier une source canonique et son périmètre.", "concept": "Sur un domaine que tu contrôles, l’inventaire des documents indexés aide à vérifier la publication attendue. Un fichier accessible publiquement ne doit pas contenir de données réservées. robots.txt et noindex concernent les robots et l’indexation : ils ne remplacent pas une authentification. Si une exposition est trouvée, restreins l’accès à la source avant de demander une suppression de l’index et vérifie les copies concernées.", "steps": ["Utilise uniquement un domaine dont tu es responsable et des fichiers fictifs.", "Compare les documents volontairement publics à ceux retournés par le moteur.", "Propose une correction d’accès sans exposer de données réelles.", "Définis un contrôle périodique et les critères de clôture."], "expected": "Un plan d’audit et de correction d’exposition documentaire.", "pitfall": "Croire que robots.txt protège un document confidentiel.", "question": "Quelle est la première action en cas d’exposition involontaire ?", "answer": "Corriger l’accès au document à la source ; retirer un résultat de recherche ne protège pas le fichier.", "lab": {"setup": "Avec un éditeur, crée un dossier web-labo et un fichier public.txt contenant uniquement EXEMPLE PUBLIC. Tu n’as besoin ni d’hébergement ni de moteur pour démontrer la différence entre indexation et accès.", "why": "robots.txt donne des instructions aux robots coopératifs. Il n’est pas un contrôle d’accès : un navigateur peut demander directement un chemin refusé à l’indexation.", "action": "Crée robots.txt contenant :\nUser-agent: *\nDisallow: /public.txt\n\nDepuis web-labo :\npython3 -m http.server 8000 --bind 127.0.0.1\nPuis ouvre http://127.0.0.1:8000/public.txt", "output": "Le navigateur affiche EXEMPLE PUBLIC malgré Disallow. Ce laboratoire local n’est pas indexé par Google ; il démontre seulement l’absence de protection serveur.", "interpret": "Le serveur Python ne bloque pas la requête parce que robots.txt ne contient pas une règle d’autorisation serveur. Pour protéger un document, place-le hors de la racine publiée ou utilise un service avec authentification et autorisation.", "trouble": "Ne publie aucun vrai secret pour faire ce test. Si le port est occupé, change-le aussi dans l’URL. Une suppression de résultat du moteur ne supprime pas le fichier à sa source.", "exercise": "Un document confidentiel n’apparaît plus dans Google mais reste accessible par son URL : est-il protégé ?", "solution": "Non. Il faut corriger l’accès à la source et vérifier le contrôle serveur, puis traiter les copies et l’index selon le contexte."}}]}];
