const decode=s=>String(s||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/&#(x[\da-f]+|\d+);/gi,(_,n)=>{const p=n[0]==='x'?parseInt(n.slice(1),16):Number(n);return p>0&&p<=0x10ffff?String.fromCodePoint(p):'';}).replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');
const clean=s=>decode(s).replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
const tag=(s,n)=>s.match(new RegExp('<'+n+'(?:\\s[^>]*)?>([\\s\\S]*?)</'+n+'>','i'))?.[1]||'';
const safeURL=s=>{try{const u=new URL(decode(s).trim());return u.protocol==='https:'?u.href:null;}catch{return null;}};
export function technicalTopic(text,fallback=null){if(/\bosint\b|open.source intelligence|geolocat|géolocal|reverse image/i.test(text))return 'OSINT';if(/\bdfir\b|forensic|investigation|incident response|réponse aux incidents/i.test(text))return 'Investigation';if(/pentest|penetration test|burp suite|red team|web security academy/i.test(text))return 'Pentest';if(/blue team|threat hunt|detection engineering|détection|hardening|durcissement|sigma rule|yara|\bsiem\b|\bedr\b|defen[cs]e/i.test(text))return 'Défense';return fallback;}
export function classify(text){if(/fuite|données personnelles|exfiltr|data breach|data leak|stolen data/i.test(text))return 'Fuite de données';if(/ransomware|rançongiciel/i.test(text))return 'Rançongiciel';if(/vulnérab|vulnerab|faille|CVE-\d/i.test(text))return 'Vulnérabilité';if(/phishing|hameçonn/i.test(text))return 'Hameçonnage';if(/attaque|attack|compromis|intrusion/i.test(text))return 'Cyberattaque';return 'Veille générale';}
export function score(text){let n=30;const reasons=['Base de veille : 30 points'];for(const [re,points,label] of [[/exploitation active|activement exploit|actively exploit|zero.day|0.day/i,30,'Exploitation active mentionnée'],[/critique|critical|urgence/i,20,'Criticité mentionnée'],[/fuite|data breach|data leak|exfiltr|rançongiciel|ransomware/i,15,'Incident touchant des données ou la disponibilité'],[/CVE-\d{4}-\d+/i,5,'Identifiant CVE présent']])if(re.test(text)){n+=points;reasons.push(label+' : +'+points);}return {score:Math.min(n,100),reasons};}
export function parseFeed(xml,source){return [...xml.matchAll(/<(item|entry)(?:\s[^>]*)?>([\s\S]*?)<\/\1>/gi)].slice(0,15).flatMap(([,kind,s])=>{const title=clean(tag(s,'title'));const url=safeURL(tag(s,'link')||[...s.matchAll(/<link\b([^>]*)>/gi)].filter(m=>!(/rel=["'](?:self|hub)["']/i.test(m[1]))).map(m=>m[1].match(/href=["']([^"']+)/i)?.[1]).find(Boolean));if(!title||!url)return [];const dateRaw=clean(tag(s,'pubDate')||tag(s,'published')||tag(s,'updated')||tag(s,'dc:date'));const stamp=Date.parse(dateRaw);const date=Number.isFinite(stamp)?new Date(stamp).toISOString():null;const summary=clean(tag(s,'description')||tag(s,'summary')||tag(s,'content:encoded')).slice(0,2400);const content=title+' '+summary;return [{id:url,title,url,date,summary,type:classify(content),topic:technicalTopic(content,source.topic||null),technical:!!source.technical||/tutorial|tutoriel|how.to|walkthrough|guide pratique|step.by.step/i.test(title),...score(content),source:source.name,sourceId:source.id,language:source.language||'fr',country:source.country||'FR',cves:[...new Set(content.match(/CVE-\d{4}-\d{4,}/gi)||[])].map(x=>x.toUpperCase()),references:extractLinks(s,url).map(x=>x.url).slice(0,12)}];});}
export function groupArticles(articles){const groups=new Map();for(const a of articles){const key=a.cves.length?'cve:'+a.cves.slice().sort().join(','):a.title.toLocaleLowerCase('fr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();const existing=groups.get(key);if(existing){existing.articles.push(a);existing.score=Math.max(existing.score,a.score);if(a.date&&(!existing.date||a.date>existing.date))existing.date=a.date;}else groups.set(key,{...a,id:key,articles:[a]});}return [...groups.values()].sort((a,b)=>(b.date||'').localeCompare(a.date||'')||b.score-a.score);}
let snapshot=null;
async function collect(){if(snapshot&&Date.now()-snapshot.time<60000)return snapshot.data;const results=await Promise.all(SOURCES.filter(s=>s.enabled).map(async s=>{try{const r=await fetch(s.url,{signal:AbortSignal.timeout(12000),headers:{Accept:'application/rss+xml, application/xml, text/xml'}});if(!r.ok)throw Error('HTTP '+r.status);const text=await limitedText(r,1500000);if(text.length>2500000)throw Error('Flux trop volumineux');const articles=parseFeed(text,s);if(!articles.length)throw Error('Aucun article lisible');return {source:s.id,status:'ok',articles};}catch(e){return {source:s.id,status:'error',message:e.name==='TimeoutError'?'Délai dépassé':'Collecte indisponible',articles:[]};}}));const data={updatedAt:new Date().toISOString(),events:groupArticles(results.flatMap(r=>r.articles)),sources:results.map(({articles,...s})=>({...s,count:articles.length})),mode:'live',ranking:'rules'};snapshot={time:Date.now(),data};return data;}
const json=(o,status=200)=>new Response(JSON.stringify(o),{status,headers:{'Content-Type':'application/json;charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
export async function authorized(request,env){
 const expected=env?.APP_ACCESS_TOKEN;
 if(typeof expected!=='string'||expected.length<24)return false;
 const supplied=request.headers.get('Authorization')||'';
 if(supplied.length>1024)return false;
 const digest=async value=>new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)));
 const [a,b]=await Promise.all([digest(supplied),digest('Bearer '+expected)]);
 let diff=0;for(let i=0;i<a.length;i++)diff|=a[i]^b[i];return diff===0;
}
